query:
CREATE TABLE STUDENT (
  SID NUMBER, 
  SNAME VARCHAR2(30), 
  AGE NUMBER, 
  COURSE VARCHAR2(20)
);

CREATE TABLE EMPLOYEE (
  EID NUMBER, 
  ENAME VARCHAR2(40), 
  SALARY NUMBER(8,2), 
  DEPTNO NUMBER
);

CREATE TABLE DEPARTMENT (
  DEPTNO NUMBER, 
  DNAME VARCHAR2(30), 
  LOCATION VARCHAR2(30)
);

CREATE TABLE BOOK (
  BOOK_ID NUMBER, 
  TITLE VARCHAR2(50), 
  AUTHOR VARCHAR2(40), 
  PRICE NUMBER
);

CREATE TABLE COURSE (
  CID NUMBER, 
  CNAME VARCHAR2(40), 
  DURATION NUMBER
);

CREATE TABLE PROJECT (
  PID NUMBER, 
  PNAME VARCHAR2(50), 
  START_DATE DATE, 
  END_DATE DATE
);

CREATE TABLE CUSTOMER (
  CID NUMBER, 
  CNAME VARCHAR2(40), 
  CITY VARCHAR2(30), 
  PHONE NUMBER
);

CREATE TABLE SALES (
  SALE_ID NUMBER, 
  PRODUCT_NAME VARCHAR2(50), 
  QUANTITY NUMBER, 
  PRICE NUMBER
);
